-- Replace the retired catalogue and features. Existing running games end cleanly;
-- their results remain recorded, and their rooms can start a rematch with the new bank.
update public.games
   set phase = 'finished', phase_deadline_at = null, ended_at = coalesce(ended_at, now()), version = version + 1,
       state = state || jsonb_build_object('phase', 'finished', 'phaseDeadline', null, 'paused', null, 'current', null, 'reveal', null,
         'finished', jsonb_build_object('reason', 'catalogUpdated', 'at', extract(epoch from now()) * 1000, 'winnerIds', '[]'::jsonb))
 where phase <> 'finished';
update public.rooms set status = 'finished' where status = 'playing';

create or replace function public.my_role_in(room uuid) returns public.player_role
language sql stable security definer set search_path = '' as $$
  select p.role from public.players p where p.room_id = room and p.user_id = (select auth.uid()) limit 1;
$$;
alter table public.players drop column kicked_at;

-- The removed lifeline is no longer accepted by the database either.
delete from public.lifeline_uses where lifeline = 'extraTime';
alter type public.lifeline_kind rename to retired_lifeline_kind;
create type public.lifeline_kind as enum ('fiftyFifty', 'pass', 'audience');
alter table public.lifeline_uses alter column lifeline type public.lifeline_kind using lifeline::text::public.lifeline_kind;
drop type public.retired_lifeline_kind;

alter table public.questions add column kind text not null default 'text' check (kind in ('text', 'image'));
alter table public.questions add column image_credit text;
alter table public.questions add column image_source text;
alter table public.questions add constraint image_questions_have_photo check (
  kind <> 'image' or (image_url is not null and length(image_url) > 0 and image_credit is not null and length(image_credit) > 0 and image_source is not null and length(image_source) > 0)
);
create index questions_kind_playable_idx on public.questions (kind, category_id, difficulty) where is_active;

-- This intentionally removes the old category bank, including its placeholder questions.
delete from public.categories where slug not in ('arte-literatura', 'deportes', 'historia', 'geografia', 'ciencia', 'entretenimiento');
alter table public.categories add constraint supported_category_slug check (slug in ('arte-literatura', 'deportes', 'historia', 'geografia', 'ciencia', 'entretenimiento'));
drop policy "categories managed by admins" on public.categories;

